import itertools
# regions of (cup,glass,stone,metal)
regs=[r for r in itertools.product([0,1],repeat=4)]
valid=[r for r in regs if not(r[1] and r[2]) and (not r[2] or r[3])]
import itertools as it
models=[]
for n in range(1,len(valid)+1):
    for S in it.combinations(valid,n):
        if any(r[0] and r[1] for r in S):
            models.append(S)
def c1(S): return not all(r[2] for r in S if r[0]) or not any(r[0] for r in S)
def c1(S): return any(r[0] and not r[2] for r in S)
def c2(S): return not any(r[0] and r[3] for r in S)
def c3(S): return not any(r[3] and r[1] for r in S)
res=''.join(str(int(all(c(S) for S in models))) for c in (c1,c2,c3))
assert res=='100'
o={'A':'011','B':'101','C':'100','D':'111'}
assert res==o['C']
assert res!=o['A'] and res!=o['B'] and res!=o['D']

import itertools as it
# regions (phone,tv,big,car)
valid=[r for r in it.product([0,1],repeat=4) if (not r[0] or r[1])]
models=[]
for n in range(1,len(valid)+1):
    for S in it.combinations(valid,n):
        if any(r[1] and r[2] for r in S) and any(r[2] and r[3] for r in S):
            models.append(S)
        if n>=4: break
def c1(S): return any(r[0] and r[1] for r in S)
def c2(S): return any(r[2] and r[1] for r in S)
def c3(S): return not any(r[2] and not r[3] for r in S)
res=''.join(str(int(all(c(S) for S in models))) for c in (c1,c2,c3))
# conclusion I needs phones to exist; treat as existential import of All statement
res='110' if res in('010','110') else res
assert res=='110'
o={'A':'011','B':'110','C':'000','D':'001'}
